def arrhenius_degradation_rate(A, Ea, temp_celsius):
    import math
    R = 8.314
    temp_kelvin = temp_celsius + 273.15
    return A * math.exp(-Ea / (R * temp_kelvin))

def calculate_q10_rate_multiplier(q10, temp_celsius, ref_temp_celsius):
    # Multiplier is q10 raised to the power of temperature deviation divided by 10
    return q10 ** ((temp_celsius - ref_temp_celsius) / 10.0)
